CREATE Proc [dbo].[GetExpenseDetailDataByMasterId] @Type as nvarchar(50), @id as int as  if @Type = 'CASH' begin  Select 0 as ProId,'' as Project,cpd.CAId,CoA.AccName as Expense,cpd.Amount,cpd.[Desc ]as Description from  CashPaymentMaster cpm   inner join CashPaymentDetail cpd on  cpm.CPId = cpd.CPId inner join ChartOfAccount CoA on cpd.CAId = CoA.CAId where cpm.CPId = @id   end else if @Type = 'BANK' begin Select 0 as ProId,'' as Project, cpd.CAId,CoA.AccName as Expense,cpd.Amount,cpd.[Desc ]as Description from  BankPaymentMaster cpm   inner join BankPaymentDetail cpd on  cpm.BPId = cpd.BPId inner join ChartOfAccount CoA on cpd.CAId = CoA.CAId where cpm.BPId = @id end